def dock_tour(fares):
    if len(fares) < 2:
        return 0
    used = []
    for row in fares:
        used.append(False)
    used[0] = True
    return tour_tail(fares, used, 0, 1)
def tour_tail(fares, used, here, count):
    if count == len(fares):
        return fares[here][0]
    best = -1
    for dest in range(1, len(fares)):
        edge = fares[here][dest]
        if used[dest] == False and edge >= 0:
            used[dest] = True
            rest = tour_tail(fares, used, dest, count + 1)
            used[dest] = False
            if rest >= 0:
                price = edge + rest
                if best < 0 or price < best:
                    best = price
    return best

